code.C:
#include <stdio.h>
#include <string.h>
int main() {
    char s[2000];
    if (fgets(s, sizeof(s), stdin)) {
        int len = strlen(s);
        while (len > 0 && (s[len-1] == '\n' || s[len-1] == '\r')) s[--len] = '\0';
        puts(s);
    }
    return 0;
}

